      var entry = { snap: c, rxMs: hfNow() };
      for (var ki = 0; ki < keys.length; ki++) hf.candidates.set(keys[ki], entry);
      while (hf.candidates.size > 16) { hf.candidates.delete(hf.candidates.keys().next().value); }
