    if (!snap) { hfLog("HF: 当前帧无对齐候选，拒绝选择（不锁已消失的人）", 2); return; }
    var box = { x0: rx0, y0: ry0, x1: rx1, y1: ry1 }, hits = [];
    for (var i = 0; i < (snap.candidates || []).length; i++) {
      var c = snap.candidates[i];
