      if (r && !r.behind && HF.rectsIntersect(r, box)) hits.push(c);
    }
    if (!hits.length) { hfLog("HF: 拖框未命中候选", 1); return; }
    if (hits.length === 1) { hfSendSelect(snap, hits[0].candidate_id); return; }
    hfLog("HF: 命中 " + hits.length + " 个候选，请在右侧列表点选确认（防前后重叠误选）", 1);
  }
