+  assert.strictEqual(HF.parseGroundRender(s).status, "invalid");
+  s = groundRenderSnap(); s.coordinate.ground_derived_id = "gd-other";
+  assert.strictEqual(HF.parseGroundRender(s).status, "unbound");
