/* ---- offline synthetic entry (?synthetic=normal|tilted|no_extrinsics) ----
 * Never connects to the board and never sends a request; it feeds the exact
 * same parse / frame-match / render path with an explicit-versioned fixture. */
function hfStartSynthetic(name) {
  var scen = HF.syntheticScenario(name);
  if (!scen) { hfLog("HF: 未知 synthetic 场景 " + name + "（可选 normal/tilted/no_extrinsics）", 2); return; }
  hf.syntheticScene = scen;
  hfLog("HF: synthetic/offline 场景 " + name + "：不连接板端、不发真实请求");
  function push() {
    if (!hf.syntheticScene) return;
    var s = hf.syntheticScene;
    hfOnRawFrame(s.logTimeNs, s.cloud);
    hfOnMessage(CAND_TOPIC, HF.packRos1String(JSON.stringify(s.snapshot)));
    hfOnMessage(STATE_TOPIC, HF.packRos1String(JSON.stringify(s.state)));
    if (s.snapshot.ground_render) hfDrawSupport();
    hfUpdatePerfPanel();
  }
  push();
  setInterval(push, 1000);
}

